def get_next_no_zero(n):
    while True:
        s = str(n)
        first_zero = s.find('0')
        if first_zero == -1:
            return n
        s_list = list(s)
        s_list[first_zero] = '1'
        for i in range(first_zero + 1, len(s_list)):
            s_list[i] = '1'
        n = int("".join(s_list))

def has_no_zero_in_range(L, R):
    if L > R: return False
    return get_next_no_zero(L) <= R

def solve_for_L(L):
    max_a = 0
    for m in range(1, L + 1):
        Q = 10**(m-1)
        # Try the largest possible N for this Q.
        N = (10**L - 1) // Q
        if has_no_zero_in_range(N * Q, N * Q + N - 1):
            max_a = max(max_a, m-1)
    return max_a

for l in range(1, 31):
    print(f"L={l}, max_a={solve_for_L(l)}")
